                        if (update != "")
                            update += ",";
                        update += "[dbo].[" + myentity.SysName + "]";
                        currEntities.Add(myentity);
                    }

                    object value = Row[myfield.DisplayName];
                    if (myfield.SystemName=="Id")
                    {
                        where += " Id = @pId ";
                        SqlParameter id=new SqlParameter("@pId", SqlDbType.UniqueIdentifier);
                        id.Value = value;
                        parameters.Add(id);
                    }
                    else
                    {
                        int pcount = parameters.Count + 1;
                        if (values != "")
                        {
                            values += ",";
                        }
                        values += "[dbo].[" + myentity.SysName + "].[" + myfield.SystemName + "] = @p" + pcount;
                        SqlParameter param = CreateParameterByType(myfield, value, pcount);
                        parameters.Add(param);

                    }

                }
                if (values != "") 
                    values = " SET "+values;
                if (where != "")
                    where = " WHERE " + where;
                if (update != "")
                    update = " UPDATE " + update;
                if (values != "" && where != "" && update != "")
                {
                    string sql = update + values + where;
                     return  database.Execute(sql, parameters.ToArray());

                }

            }


        }
    }

    if (EditType != null && EditType.ToString() == "New")
    {
        using (DataBase database = new DataBase(_context))
        {

            Views myView = _context.Views.SingleOrDefault(a => a.Id.ToString().ToLower() == ViewId.ToLower());
            if (myView == null)
            {
                myView = _context.Views.SingleOrDefault(a => a.DisplayName == ViewId);
            }
            //select the view by view Id

            if (myView != null)
            {
                List<DataSourceFields> fields = _context.DataSourceFields.Where(a => a.DataSourceId == myView.DataSourceId).ToList();
                List<SqlParameter> parameters = new List<SqlParameter>();
                List<Entities> currEntities = new List<Entities>();
                string values = "", columns="", tables="";
                for (var i = 0; i < fields.Count; i++)
                {
                    DataSourceFields field = fields[i];
                    //for now assume there is only one data entity in this case.
                    Fields myfield = _context.Fields.FirstOrDefault(a => a.Id.ToString() == field.FieldId);
                    Entities myentity = currEntities.FirstOrDefault(a => a.Id.ToString().ToLower() == field.EntityId.ToLower());
                    if (myentity == null)
                    {
                        myentity = _context.Entities.FirstOrDefault(a => a.Id.ToString() == field.EntityId);
                        if (tables != "")
                            tables += ",";
                        tables += "[dbo].[" + myentity.SysName + "]";
                        currEntities.Add(myentity);
                    }

                    object value = Row[myfield.DisplayName];
                    if (myfield.SystemName != "Id")
                    {

                        int pcount = parameters.Count + 1;
                        if (values != "")
                        {
                            values += ",";
                        }
                        if (columns != "")
                        {
                            columns += ",";
                        }
                        columns +="[dbo].[" + myentity.SysName + "].[" + myfield.SystemName + "]";
                        values += " @p" + pcount;
                        SqlParameter param = CreateParameterByType(myfield, value, pcount);
                        parameters.Add(param);

                    }

                }
                if (values != "")
                    values = " VALUES ( " + values+")";
                if (columns != "")
                    columns = " ( " + columns+") ";
                if (tables != "")
                    tables = " INSERT INTO " + tables;
                if (values != "" && tables != "" && values != "")
                {
                    string sql = tables + columns + values ;
                    return database.Execute(sql, parameters.ToArray());

                }

            }


        }
    }
